    {
		TestBits bits =
			startTest(typeof(MethodTakesBooleanBoxed).getMethod("theMethod", typeof(Boolean)));
		assertTrue(bits.getComponent("b") is PropertyBoolean);
		bits.setArg("b", true);
		Map<string, object> values = bits.invoke();
		assertEquals(true, values.get("b"));
	}
}
